/// End of the number starting at `start`. Numbers extend over digits, `_`
/// and `.`; spelling is validated separately.
pub fn number_end(bytes: &[u8], start: usize) -> usize {
    start
        + 1
        + bytes[start + 1..]
            .iter()
            .take_while(|&&b| b.is_ascii_digit() || b == b'_' || b == b'.')
            .count()
}

